package com.diberlog.jarvis.mobile;

import org.json.*;
import org.xmlpull.v1.XmlPullParser;
import android.util.Xml;
import java.net.*;
import java.io.*;
import java.nio.charset.StandardCharsets;

final class PublicData {
    static String read(InputStream input,int limit)throws Exception{if(input==null)throw new IOException("Источник не ответил");try(InputStream in=input;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("Ответ источника слишком большой");out.write(b,0,n);}return out.toString("UTF-8");}}
    static String get(String address)throws Exception{URL url=new URL(address);if(!"https".equals(url.getProtocol())||url.getUserInfo()!=null)throw new IOException("Укажите HTTPS-ссылку без логина и пароля");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","JarvisMobileLab/1.0");try{int status=c.getResponseCode();if(status!=200)throw new IOException("Источник вернул HTTP "+status+". Проверьте ссылку и интернет");return read(c.getInputStream(),2*1024*1024);}catch(SocketTimeoutException e){throw new IOException("Источник не ответил вовремя. Кэш сохранён; попробуйте позже");}finally{c.disconnect();}}
    static String news(String url)throws Exception{String xml=get(url);String upper=xml.toUpperCase(java.util.Locale.ROOT);if(upper.contains("<!DOCTYPE")||upper.contains("<!ENTITY"))throw new IOException("Небезопасный формат RSS: DTD не поддерживается");XmlPullParser p=Xml.newPullParser();p.setFeature(XmlPullParser.FEATURE_PROCESS_NAMESPACES,false);p.setInput(new StringReader(xml));JSONArray items=new JSONArray();String title="",link="";boolean inside=false;for(int event=p.getEventType();event!=XmlPullParser.END_DOCUMENT;event=p.next()){if(event==XmlPullParser.START_TAG){String tag=p.getName();if(tag.equals("item")||tag.equals("entry")){inside=true;title="";link="";}else if(inside&&tag.equals("title"))title=p.nextText();else if(inside&&tag.equals("link")){String href=p.getAttributeValue(null,"href");link=href==null?p.nextText():href;}}else if(event==XmlPullParser.END_TAG&&(p.getName().equals("item")||p.getName().equals("entry"))){inside=false;if(!title.isEmpty()&&(link.startsWith("https://")||link.startsWith("http://")))items.put(new JSONObject().put("title",title.substring(0,Math.min(1000,title.length()))).put("url",link));if(items.length()>=30)break;}}if(items.length()==0)throw new IOException("В RSS не найдены новости с ссылками. Попробуйте другой источник");return items.toString();}
    static String weather(String city)throws Exception{if(city.isEmpty()||city.length()>100)throw new IOException("Введите город до 100 символов");String encoded=URLEncoder.encode(city,"UTF-8");JSONObject geo=new JSONObject(get("https://geocoding-api.open-meteo.com/v1/search?name="+encoded+"&count=1&language=ru&format=json"));JSONArray results=geo.optJSONArray("results");if(results==null||results.length()==0)throw new IOException("Город не найден. Уточните название");JSONObject place=results.getJSONObject(0);double lat=place.getDouble("latitude"),lon=place.getDouble("longitude");JSONObject forecast=new JSONObject(get("https://api.open-meteo.com/v1/forecast?latitude="+lat+"&longitude="+lon+"&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max,weather_code&timezone=auto&forecast_days=7"));JSONObject daily=forecast.getJSONObject("daily");JSONArray dates=daily.getJSONArray("time"),max=daily.getJSONArray("temperature_2m_max"),min=daily.getJSONArray("temperature_2m_min"),rain=daily.getJSONArray("precipitation_probability_max");StringBuilder text=new StringBuilder(place.optString("name")).append(" · ").append(place.optString("country")).append('\n');for(int i=0;i<dates.length();i++)text.append(dates.getString(i)).append(": ").append(min.opt(i)).append("…").append(max.opt(i)).append(" °C · осадки ").append(rain.opt(i)).append("%\n");return text.toString();}
}
